/* Pixel theme: palette #2d2a4a (bg), #f5e6d3 (card), #6c5b7b (accent), #f67280 (highlight), #4a3f5e (text) */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #2d2a4a;
  color: #f5e6d3;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: #f5e6d3;
  color: #4a3f5e;
  border: 4px solid #6c5b7b;
  border-radius: 0;
  box-shadow: 8px 8px 0 #6c5b7b;
  padding: 24px;
  max-width: 600px;
  width: 100%;
  image-rendering: pixelated;
}

header {
  text-align: center;
  margin-bottom: 24px;
}

h1 {
  font-size: 1.75rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #4a3f5e;
  margin-bottom: 8px;
}

.subtitle {
  font-size: 1rem;
  color: #6c5b7b;
}

h2 {
  font-size: 1.25rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #4a3f5e;
  margin-bottom: 12px;
  border-bottom: 2px solid #6c5b7b;
  padding-bottom: 4px;
}

.form-section {
  margin-bottom: 24px;
}

.form-group {
  margin-bottom: 16px;
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: 4px;
  font-size: 1rem;
}

input, select {
  width: 100%;
  padding: 10px 12px;
  font-size: 1rem;
  font-family: inherit;
  border: 3px solid #6c5b7b;
  border-radius: 0;
  background: #fff;
  color: #4a3f5e;
  transition: border-color 0.1s, box-shadow 0.1s;
}

input:focus, select:focus {
  outline: none;
  border-color: #f67280;
  box-shadow: 0 0 0 3px rgba(246, 114, 128, 0.3);
}

input:hover, select:hover {
  border-color: #f67280;
}

button {
  display: inline-block;
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  font-family: inherit;
  background: #6c5b7b;
  color: #f5e6d3;
  border: 3px solid #4a3f5e;
  border-radius: 0;
  cursor: pointer;
  transition: background 0.1s, transform 0.1s, box-shadow 0.1s;
  box-shadow: 4px 4px 0 #4a3f5e;
}

button:hover {
  background: #f67280;
  color: #2d2a4a;
}

button:focus-visible {
  outline: 3px solid #f67280;
  outline-offset: 2px;
}

button:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

.error {
  color: #b33a3a;
  font-weight: 600;
  margin-top: 8px;
  min-height: 1.5em;
}

.summary-section, .expenses-section {
  margin-bottom: 24px;
}

#summary {
  background: #fff;
  border: 3px solid #6c5b7b;
  padding: 16px;
  font-size: 1rem;
}

#summary .placeholder, .expense-list .placeholder {
  color: #6c5b7b;
  font-style: italic;
  text-align: center;
  padding: 8px;
}

#summary p {
  margin: 8px 0;
}

#summary strong {
  color: #4a3f5e;
}

.expense-list {
  list-style: none;
  background: #fff;
  border: 3px solid #6c5b7b;
  padding: 0;
  max-height: 200px;
  overflow-y: auto;
}

.expense-list li {
  padding: 10px 16px;
  border-bottom: 2px solid #e0d5c8;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 1rem;
}

.expense-list li:last-child {
  border-bottom: none;
}

.expense-list .expense-desc {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  margin-right: 12px;
}

.expense-list .expense-amount {
  font-weight: 700;
  color: #6c5b7b;
}

@media (max-width: 480px) {
  .card {
    padding: 16px;
    box-shadow: 4px 4px 0 #6c5b7b;
  }
  h1 {
    font-size: 1.5rem;
  }
  button {
    width: 100%;
  }
}

const friends = ['Alice', 'Bob', 'Charlie'];
let expenses = [];

const form = document.getElementById('expense-form');
const payerSelect = document.getElementById('payer');
const amountInput = document.getElementById('amount');
const descInput = document.getElementById('description');
const errorMsg = document.getElementById('error-message');
const summaryDiv = document.getElementById('summary');
const expenseList = document.getElementById('expense-list');

function formatCurrency(cents) {
  return '$' + (cents / 100).toFixed(2);
}

function renderSummary() {
  if (expenses.length === 0) {
    summaryDiv.innerHTML = '<p class="placeholder">No expenses yet. Add one above!</p>';
    return;
  }
  const totalCents = expenses.reduce((sum, e) => sum + e.amountCents, 0);
  const fairShareCents = totalCents / friends.length;
  const paidCents = {};
  friends.forEach(f => paidCents[f] = 0);
  expenses.forEach(e => paidCents[e.payer] += e.amountCents);

  let html = `<p><strong>Total spent:</strong> ${formatCurrency(totalCents)}</p>`;
  html += `<p><strong>Fair share per person:</strong> ${formatCurrency(fairShareCents)}</p>`;
  html += '<ul style="list-style:none;padding:0;margin-top:12px;">';
  friends.forEach(f => {
    const balance = paidCents[f] - fairShareCents;
    let status;
    if (balance > 0.5) status = `is owed ${formatCurrency(balance)}`;
    else if (balance < -0.5) status = `owes ${formatCurrency(-balance)}`;
    else status = 'is settled';
    html += `<li style="padding:4px 0;"><strong>${f}</strong> paid ${formatCurrency(paidCents[f])} — ${status}</li>`;
  });
  html += '</ul>';
  summaryDiv.innerHTML = html;
}

function renderExpenses() {
  if (expenses.length === 0) {
    expenseList.innerHTML = '<li class="placeholder">No expenses added.</li>';
    return;
  }
  expenseList.innerHTML = expenses.map(e =>
    `<li><span class="expense-desc">${e.description || 'Expense'}</span> <span class="expense-amount">${formatCurrency(e.amountCents)} (${e.payer})</span></li>`
  ).join('');
}

function addExpense(payer, amountCents, description) {
  expenses.push({ payer, amountCents, description });
  renderSummary();
  renderExpenses();
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  errorMsg.textContent = '';
  const payer = payerSelect.value;
  const amount = parseFloat(amountInput.value);
  const desc = descInput.value.trim();

  if (isNaN(amount) || amount <= 0) {
    errorMsg.textContent = 'Please enter a positive amount.';
    amountInput.focus();
    return;
  }
  const amountCents = Math.round(amount * 100);
  addExpense(payer, amountCents, desc);
  amountInput.value = '';
  descInput.value = '';
  amountInput.focus();
});

// Initial render
renderSummary();
renderExpenses();
